style.css:
@-moz-document domain("pinterest.com") {
/* TEST: pastel pink page background */
  html,
  body,
  #__PWS_ROOT__,
  #root {
    background-color: #fff3f8 !important;
  }

  /* ------------------------------------------
     1. COLOR PALETTE
     Edit these values to change the whole theme
     ------------------------------------------ */

  :root {
  --pastel-bg: #FCE8EF;
  --pastel-pink: #f4c6dc;
  --pastel-pink-dark: #d98db5;
  --pastel-lavender: #e4daf4;
  --pastel-blue: #dceefa;
  --pastel-mint: #dff2e8;
  --pastel-border: #F8BFD1;
  --pastel-text: #F07FA3;
  --pastel-muted: #9c8298;
  --pastel-white: #fffdfd;
  --pastel-hover: #fce5ef;
  --pastel-shadow: rgba(190, 130, 166, 0.12);
  --pastel-radius: 16px;
}

  /* ------------------------------------------
     2. GLOBAL BACKGROUND AND TYPOGRAPHY
     ------------------------------------------ */

  html,
  body,
  #__PWS_ROOT__,
  #root {
    background-color: var(--pastel-bg) !important;
    color: var(--pastel-text) !important;
    font-family: "Nunito", "Segoe UI", sans-serif !important;
  }

  body,
  button,
  input,
  textarea,
  select {
    font-family: "Nunito", "Segoe UI", sans-serif !important;
  }

  /* Main content surfaces */
  main,
  [role="main"] {
    background-color: var(--pastel-bg) !important;
  }

  /* ------------------------------------------
     3. SIDEBAR AND NAVIGATION
     ------------------------------------------ */

  nav,
  aside,
  [role="navigation"] {
    background-color: var(--pastel-white) !important;
    border-color: var(--pastel-border) !important;
  }

  /* Sidebar and navigation links */
  nav a,
  aside a,
  [role="navigation"] a {
    color: var(--pastel-text) !important;
    border-radius: 12px !important;
    transition:
      background-color 0.2s ease,
      color 0.2s ease !important;
  }

  nav a:hover,
  aside a:hover,
  [role="navigation"] a:hover {
    background-color: var(--pastel-hover) !important;
    color: var(--pastel-pink-dark) !important;
  }

  /* Navigation buttons */
  nav button,
  aside button,
  [role="navigation"] button {
    border-radius: 12px !important;
    transition: background-color 0.2s ease !important;
  }

  nav button:hover,
  aside button:hover,
  [role="navigation"] button:hover {
    background-color: var(--pastel-hover) !important;
  }

  /* Navigation icons: color SVG icons without replacing them */
  nav svg,
  aside svg,
  [role="navigation"] svg {
    color: var(--pastel-muted);
    transition: color 0.2s ease !important;
  }

  nav a:hover svg,
  aside a:hover svg,
  [role="navigation"] a:hover svg,
  nav button:hover svg,
  aside button:hover svg,
  [role="navigation"] button:hover svg {
    color: var(--pastel-pink-dark) !important;
  }

  /* ------------------------------------------
     4. SEARCH BAR
     ------------------------------------------ */

  /* Pinterest search bar — make the ENTIRE bar pink */

[role="search"],
[data-test-id="search-box"],
[data-test-id="search-box-container"] {
  background-color: #FFE4EF !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 1157px !important;
}

/* Inner search input */
[role="search"] input,
[data-test-id="search-box"] input,
input[placeholder*="Search"],
input[aria-label*="Search"] {
  background-color: #FFE4EF !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  border-radius: 28px !important;
}

/* Keep it pink when selected */
[role="search"]:focus-within,
[data-test-id="search-box"]:focus-within,
[data-test-id="search-box-container"]:focus-within {
  background-color: #FFE4EF !important;
  border: none !important;
  box-shadow: none !important;
}

  /* ------------------------------------------
     5. PIN BORDERS
     ------------------------------------------ */

  /* Rounded pastel frames around pins */
  [data-test-id="pin"],
  [data-test-id="pinWrapper"],
  [data-test-id="pinrep"],
  [data-grid-item="true"] {
    border: 2px solid var(--pastel-border) !important;
    border-radius: var(--pastel-radius) !important;
    overflow: hidden !important;
    background-color: var(--pastel-white) !important;
    transition:
      border-color 0.2s ease,
      box-shadow 0.2s ease,
      transform 0.2s ease !important;
  }

  [data-test-id="pin"]:hover,
  [data-test-id="pinWrapper"]:hover,
  [data-test-id="pinrep"]:hover,
  [data-grid-item="true"]:hover {
    border-color: var(--pastel-pink-dark) !important;
    box-shadow: 0 5px 16px var(--pastel-shadow) !important;
  }

  /* Pin images */
  [data-test-id="pin"] img,
  [data-test-id="pinWrapper"] img,
  [data-test-id="pinrep"] img,
  [data-grid-item="true"] img {
    border-radius: 12px !important;
  }

  /* ------------------------------------------
     6. BUTTONS AND INTERACTIVE ELEMENTS
     ------------------------------------------ */

  button {
    transition:
      background-color 0.2s ease,
      border-color 0.2s ease,
      color 0.2s ease !important;
  }

  /* Soft pastel treatment for secondary buttons */
  button:not(:disabled):hover {
    border-color: var(--pastel-border);
  }

  /* Avoid changing the appearance of Pinterest's
     main red branding buttons unnecessarily. */

  /* ------------------------------------------
     7. TEXT AND LINKS
     ------------------------------------------ */

  a {
    transition: color 0.2s ease !important;
  }

  a:hover {
    color: var(--pastel-pink-dark);
  }

  h1,
  h2,
  h3,
  h4 {
    color: var(--pastel-text);
  }

  /* ------------------------------------------
     8. SCROLLBAR
     ------------------------------------------ */

  * {
    scrollbar-width: thin;
    scrollbar-color: var(--pastel-pink) var(--pastel-bg);
  }

  ::-webkit-scrollbar {
    width: 9px;
    height: 9px;
  }

  ::-webkit-scrollbar-track {
    background: var(--pastel-bg);
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--pastel-pink);
    border: 2px solid var(--pastel-bg);
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--pastel-pink-dark);
  }

  /* ------------------------------------------
     9. MENUS AND POPOVERS
     ------------------------------------------ */

  [role="menu"],
  [role="listbox"],
  [role="dialog"] {
    background-color: var(--pastel-white) !important;
    color: var(--pastel-text) !important;
    border-color: var(--pastel-border) !important;
    border-radius: 16px !important;
    box-shadow: 0 6px 22px var(--pastel-shadow) !important;
  }

  [role="menuitem"]:hover,
  [role="option"]:hover {
    background-color: var(--pastel-hover) !important;
  }

  /* ------------------------------------------
     10. SELECTION COLOR
     ------------------------------------------ */

  ::selection {
    background-color: var(--pastel-lavender);
    color: var(--pastel-text);
  }
}
